Single Number - II.source:
import java.util.*;

public class Solution {
  public static int solve(int[] a) {
    int once = 0, twice = 0;
    for (int x : a) {
      once = (once ^ x) & ~twice;
      twice = (twice ^ x) & ~once;
    }
    return once;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {2, 2, 3, 2}));
  }
}

Single Number - III.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    int xor = 0;
    for (int x : a) xor ^= x;
    int bit = xor & -xor, p = 0, q = 0;
    for (int x : a)
      if ((x & bit) == 0) p ^= x;
      else q ^= x;
    return p < q ? new int[] {p, q} : new int[] {q, p};
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {1, 2, 1, 3, 2, 5})));
  }
}

Divide two numbers without multiplicatio.source:
import java.util.*;

public class Solution {
  public static int solve(int dividend, int divisor) {
    if (divisor == 0) throw new ArithmeticException("division by zero");
    if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
    long a = Math.abs((long) dividend), b = Math.abs((long) divisor), q = 0;
    for (int bit = 31; bit >= 0; bit--)
      if ((a >> bit) >= b) {
        a -= b << bit;
        q |= 1L << bit;
      }
    return (int) ((dividend < 0) ^ (divisor < 0) ? -q : q);
  }

  public static void main(String[] args) {
    System.out.println(solve(43, -8));
  }
}

Power Set Bit Manipulation.source:
import java.util.*;

public class Solution {
  public static List<List<Integer>> solve(int[] a) {
    if (a.length > 20) throw new IllegalArgumentException("output is exponential; demo limit 20");
    List<List<Integer>> out = new ArrayList<>();
    for (int mask = 0; mask < (1 << a.length); mask++) {
      List<Integer> row = new ArrayList<>();
      for (int i = 0; i < a.length; i++) if ((mask & (1 << i)) != 0) row.add(a[i]);
      out.add(row);
    }
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 2}));
  }
}

XOR of numbers in a given range.source:
import java.util.*;

public class Solution {
  private static int prefix(int n) {
    switch (n & 3) {
      case 0:
        return n;
      case 1:
        return 1;
      case 2:
        return n + 1;
      default:
        return 0;
    }
  }

  public static int solve(int l, int r) {
    if (l < 0 || r < l) throw new IllegalArgumentException();
    return prefix(r) ^ (l == 0 ? 0 : prefix(l - 1));
  }

  public static void main(String[] args) {
    System.out.println(solve(3, 9));
  }
}

